"use strict";const e=require("./request.js");exports.adminCheck=function(){return e.get("/admin/recipes/check")},exports.adminGetGenerationConfig=function(){return e.get("/admin/recipes/generation-config")},exports.adminRecipeBatchImage=function(n){return e.post("/admin/recipes/batch-image",{count:n})},exports.adminRecipeBatchSetImage=function(n){return e.post("/admin/recipes/batch-set-image",{items:n})},exports.adminRecipeDelete=function(n){return e.del(`/admin/recipes/${n}`)},exports.adminRecipeDetail=function(n){return e.get(`/admin/recipes/${n}`)},exports.adminRecipeGenImage=function(n,t=!1){return e.post(`/admin/recipes/${n}/image${t?"?force=true":""}`,{})},exports.adminRecipeList=function(n){return e.get("/admin/recipes",n)},exports.adminRecipeSetImage=function(n,t){return e.post(`/admin/recipes/${n}/set-image`,{imageUrl:t})},exports.adminRecipeStats=function(){return e.get("/admin/recipes/stats")},exports.adminRecipeUpdate=function(n,t){return e.put(`/admin/recipes/${n}`,t)},exports.adminRunGenerationNow=function(n){return e.post("/admin/recipes/generation-run",{count:n})},exports.adminUpdateGenerationConfig=function(n){return e.put("/admin/recipes/generation-config",n)};
